function pulse(x,y,z,color=0xa8efff){if(!ready)return;const ring=new THREE.Mesh(new THREE.TorusGeometry(1,.035,4,80),new THREE.MeshBasicMaterial({color,transparent:true,opacity:1}));ring.rotation.x=-Math.PI/2;ring.position.set(x,y,z);scene.add(ring);ringPulses.push({obj:ring,age:0});if(ringPulses.length>15){const old=ringPulses.shift();scene.remove(old.obj);old.obj.geometry.dispose();old.obj.material.dispose()}}
function addLamp(){const a=Math.random()*Math.PI*2,r=4+Math.random()*4;const g=lantern(Math.sin(a)*r,1.2,Math.cos(a)*r+5);g.scale.setScalar(.6);floating.push({obj:g,base:1.2,phase:Math.random()*6,kind:'offering'});const offerings=floating.filter(f=>f.kind==='offering');if(offerings.length>24){const old=offerings[0];scene.remove(old.obj);old.obj.traverse(o=>{o.geometry?.dispose();if(o.isSprite){o.material.map?.dispose();o.material.dispose()}});floating.splice(floating.indexOf(old),1)}pulse(0,.3,3)}
function changeView(key){if(!positions[key])return;view=key;const p=positions[key];goalCam.set(...p.cam);goalTarget.set(...p.target);orbit=tilt=0;zoom=1;document.querySelectorAll('.destination').forEach(b=>{b.classList.toggle('active',b.dataset.view===key);b.setAttribute('aria-pressed',String(b.dataset.view===key))});$('#realm-label').textContent=p.title;$('#action-caption').textContent=p.caption;$('#action-label').textContent=p.label;$('#action-icon').textContent=p.icon;if(!entered)enter();}
function enter(){const first=!entered;entered=true;document.body.classList.add('exploring');$('#world-hint').textContent='Chạm đèn, chuông hoặc mặt hồ để tương tác';goalCam.set(19,13,26);if(view!=='temple')goalCam.set(...positions[view].cam);if(first){experience.enter();worldFx?.burst('entry')}$('#action').focus({preventScroll:true})}
$('#enter').onclick=enter;document.querySelectorAll('.destination').forEach(b=>b.onclick=()=>changeView(b.dataset.view));
$('#action').onclick=()=>{if(!ready){toast('Cảnh 3D chưa sẵn sàng. Hãy thử tải lại trang.');return}if(!entered)enter();if(view==='temple'){lamps++;storage.set('lamps',lamps);$('#lamp-count').textContent=lamps;addLamp();tone();experience.ritual('lamp')}else if(view==='bell'){bellPulse=2.7;for(let i=0;i<3;i++)pulse(-11,.5+i*.3,1,0xf7a8d5);tone(true);experience.ritual('bell');if(!sound)toast('Bật âm thanh ở góc trên để nghe tiếng chuông.')}else $('#wish-dialog').showModal()};
