let last=0;function animate(now=0){requestAnimationFrame(animate);if(document.hidden||!ready)return;if(low&&now-last<32)return;const dt=Math.min((now-last)/1000||.016,.05);last=now;const t=reduced?0:now*.001;const target=goalCam.clone().sub(goalTarget).multiplyScalar(zoom);target.applyAxisAngle(new THREE.Vector3(0,1,0),orbit);target.y=Math.max(3,target.y+tilt);target.add(goalTarget);if(innerWidth<650&&!entered){target.set(26,20,38)}camera.position.lerp(target,reduced?1:.035);look.lerp(goalTarget,reduced?1:.045);camera.lookAt(look);stars.rotation.y=t*.006;for(let i=floating.length-1;i>=0;i--){const f=floating[i];if(f.kind==='wish'){const age=(performance.now()-f.start)/1000;f.obj.position.y=f.base+age*1.8;f.obj.position.x+=Math.sin(t)*dt*.6;if(age>22){scene.remove(f.obj);f.obj.traverse(o=>{o.geometry?.dispose();if(o.isSprite){o.material.map?.dispose();o.material.dispose()}});floating.splice(i,1)}}else if(f.kind==='bell'){f.obj.rotation.z=Math.sin(t*12)*bellPulse*.09}else{f.obj.position.y=f.base+Math.sin(t*.8+f.phase)*.17;if(f.kind==='crystal')f.obj.rotation.y=t*.35}}bellPulse=Math.max(0,bellPulse-dt*.7);for(let i=ringPulses.length-1;i>=0;i--){const p=ringPulses[i];p.age+=dt;p.obj.scale.setScalar(1+p.age*3);p.obj.material.opacity=Math.max(0,1-p.age/2);if(p.age>2){scene.remove(p.obj);p.obj.geometry.dispose();p.obj.material.dispose();ringPulses.splice(i,1)}}worldFx?.update(reduced?0:dt);renderer.render(scene,camera)}
